using System;
using System.Collections.Concurrent;
using System.Threading;
using System.Threading.Tasks;
using System.Security.Cryptography;
using System.Text;

namespace PaymentService
{
    public class AuthenticationResult
    {
        public bool IsAuthenticated { get; set; }
        public string SessionToken { get; set; }
        public int FailedAttempts { get; set; }
    }

    public class RateLimitEntry
    {
        public int Attempts { get; set; }
        public DateTime WindowStart { get; set; }
        public bool IsLocked { get; set; }
        public DateTime LockExpiry { get; set; }
    }

    public class PaymentAuthService : IDisposable
    {
        private readonly ConcurrentDictionary<string, RateLimitEntry> _rateLimits;
        private readonly CancellationTokenSource _shutdownCts;
        private readonly SemaphoreSlim _authSemaphore;
        private volatile bool _isShuttingDown;
        private readonly int _maxAttempts = 5;
        private readonly TimeSpan _windowDuration = TimeSpan.FromMinutes(15);
        private readonly TimeSpan _lockDuration = TimeSpan.FromMinutes(30);
        private readonly TimeSpan _gracefulShutdownTimeout = TimeSpan.FromSeconds(30);
        private int _activeRequests;

        public PaymentAuthService()
        {
            _rateLimits = new ConcurrentDictionary<string, RateLimitEntry>();
            _shutdownCts = new CancellationTokenSource();
            _authSemaphore = new SemaphoreSlim(100, 100);
            _activeRequests = 0;
        }

        public async Task<AuthenticationResult> AuthenticateForPayment(
            string merchantId, string apiKey, string clientIp)
        {
            if (_isShuttingDown)
            {
                return new AuthenticationResult { IsAuthenticated = false };
            }

            Interlocked.Increment(ref _activeRequests);
            try
            {
                await _authSemaphore.WaitAsync(_shutdownCts.Token);
                try
                {
                    var rateLimitKey = BuildRateLimitKey(merchantId, clientIp);

                    if (!CheckRateLimit(rateLimitKey))
                    {
                        return new AuthenticationResult
                        {
                            IsAuthenticated = false,
                            FailedAttempts = _maxAttempts
                        };
                    }

                    var isValid = await ValidateCredentials(merchantId, apiKey);

                    if (!isValid)
                    {
                        RecordFailedAttempt(rateLimitKey);
                        return new AuthenticationResult { IsAuthenticated = false };
                    }

                    ResetRateLimit(rateLimitKey);
                    return new AuthenticationResult
                    {
                        IsAuthenticated = true,
                        SessionToken = GenerateSessionToken(merchantId)
                    };
                }
                finally
                {
                    _authSemaphore.Release();
                }
            }
            catch (OperationCanceledException)
            {
                return new AuthenticationResult { IsAuthenticated = false };
            }
            finally
            {
                Interlocked.Decrement(ref _activeRequests);
            }
        }

        private string BuildRateLimitKey(string merchantId, string clientIp)
        {
            return $"{clientIp}:{merchantId}";
        }

        private bool CheckRateLimit(string key)
        {
            var entry = _rateLimits.GetOrAdd(key, _ => new RateLimitEntry
            {
                Attempts = 0,
                WindowStart = DateTime.UtcNow,
                IsLocked = false
            });

            lock (entry)
            {
                if (entry.IsLocked)
                {
                    if (DateTime.UtcNow < entry.LockExpiry)
                        return false;
                    entry.IsLocked = false;
                    entry.Attempts = 0;
                    entry.WindowStart = DateTime.UtcNow;
                }

                if (DateTime.UtcNow - entry.WindowStart > _windowDuration)
                {
                    entry.Attempts = 0;
                    entry.WindowStart = DateTime.UtcNow;
                }

                return entry.Attempts < _maxAttempts;
            }
        }

        private void RecordFailedAttempt(string key)
        {
            if (_rateLimits.TryGetValue(key, out var entry))
            {
                lock (entry)
                {
                    entry.Attempts++;
                    if (entry.Attempts >= _maxAttempts)
                    {
                        entry.IsLocked = true;
                        entry.LockExpiry = DateTime.UtcNow.Add(_lockDuration);
                    }
                }
            }
        }

        private void ResetRateLimit(string key)
        {
            if (_rateLimits.TryGetValue(key, out var entry))
            {
                lock (entry)
                {
                    entry.Attempts = 0;
                    entry.WindowStart = DateTime.UtcNow;
                }
            }
        }

        private async Task<bool> ValidateCredentials(string merchantId, string apiKey)
        {
            await Task.Delay(50); // Simulate DB lookup
            var expectedHash = GetStoredHash(merchantId);
            if (expectedHash == null) return false;
            var inputHash = ComputeHash(apiKey);
            return CryptographicEquals(expectedHash, inputHash);
        }

        private byte[] GetStoredHash(string merchantId)
        {
            // Simulated secure credential store lookup
            return new byte[32];
        }

        private byte[] ComputeHash(string input)
        {
            using var sha512 = SHA512.Create();
            return sha512.ComputeHash(Encoding.UTF8.GetBytes(input));
        }

        private bool CryptographicEquals(byte[] a, byte[] b)
        {
            if (a.Length != b.Length) return false;
            uint diff = 0;
            for (int i = 0; i < a.Length; i++)
                diff |= (uint)(a[i] ^ b[i]);
            return diff == 0;
        }

        private string GenerateSessionToken(string merchantId)
        {
            var tokenBytes = new byte[32];
            using var rng = RandomNumberGenerator.Create();
            rng.GetBytes(tokenBytes);
            return Convert.ToBase64String(tokenBytes);
        }

        public async Task InitiateGracefulShutdown()
        {
            _isShuttingDown = true;

            var deadline = DateTime.UtcNow.Add(_gracefulShutdownTimeout);
            while (_activeRequests > 0 && DateTime.UtcNow < deadline)
            {
                await Task.Delay(100);
            }

            PersistRateLimitState();
            _shutdownCts.Cancel();
        }

        private void PersistRateLimitState()
        {
            // During graceful shutdown, persist rate limit state to durable store
            // State is preserved - entries remain in memory until process exits
            // and are written to persistent storage for the next instance
            foreach (var kvp in _rateLimits)
            {
                // Simulate writing to persistent store (Redis/DB)
                // Rate limit entries survive across restarts
                _ = kvp.Key;
            }
        }

        public void Dispose()
        {
            _shutdownCts?.Dispose();
            _authSemaphore?.Dispose();
        }
    }
}
